create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,email,full_name,avatar_url) values (new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url') on conflict (id) do update set email=excluded.email,full_name=excluded.full_name,avatar_url=excluded.avatar_url,updated_at=now(); return new; end; $$;
create trigger on_auth_user_created after insert or update of email, raw_user_meta_data on auth.users for each row execute procedure public.handle_new_user();
create table public.meetings (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, name text not null, source_language_code text not null, target_language_code text not null, status text not null default 'created', created_at timestamptz not null default now(), unique(owner_user_id,id));
create table public.meeting_segments (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, meeting_id uuid not null, sequence integer not null, status text not null default 'created', started_at timestamptz, ended_at timestamptz, unique(owner_user_id,id), unique(owner_user_id,meeting_id,sequence), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade);
create table public.sessions (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, meeting_id uuid, segment_id uuid, status text not null default 'created', source_language_code text, target_language_code text not null, started_at timestamptz, ended_at timestamptz, unique(owner_user_id,id), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade, foreign key(owner_user_id,segment_id) references public.meeting_segments(owner_user_id,id) on delete cascade);
create table public.subtitle_cues (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, session_id uuid not null, sequence integer not null, source_text text not null, translated_text text, source_version integer not null default 1, translation_version integer not null default 0, started_at timestamptz, ended_at timestamptz, unique(owner_user_id,id), unique(owner_user_id,session_id,sequence), foreign key(owner_user_id,session_id) references public.sessions(owner_user_id,id) on delete cascade);
create table public.translation_requests (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, cue_id uuid, idempotency_key text not null, source_version integer not null, created_at timestamptz not null default now(), unique(owner_user_id,id), unique(owner_user_id,cue_id,idempotency_key), foreign key(owner_user_id,cue_id) references public.subtitle_cues(owner_user_id,id) on delete cascade);
create table public.translation_executions (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, translation_request_id uuid not null, attempt integer not null default 1, status text not null default 'queued', created_at timestamptz not null default now(), unique(owner_user_id,id), unique(owner_user_id,translation_request_id,attempt), foreign key(owner_user_id,translation_request_id) references public.translation_requests(owner_user_id,id) on delete cascade);
create table public.translation_outputs (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, translation_execution_id uuid not null, version integer not null, translated_text text not null, created_at timestamptz not null default now(), unique(owner_user_id,id), unique(owner_user_id,translation_execution_id,version), foreign key(owner_user_id,translation_execution_id) references public.translation_executions(owner_user_id,id) on delete cascade);
create table public.glossary_categories (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, label text not null, sort_order integer not null default 0, unique(owner_user_id,id), unique(owner_user_id,label));
create table public.glossary_entries (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, category_id uuid, source text not null, translation text not null, source_language_code text not null, target_language_code text not null, unique(owner_user_id,id), unique(owner_user_id,source,translation,source_language_code,target_language_code), foreign key(owner_user_id,category_id) references public.glossary_categories(owner_user_id,id) on delete set null);
create table public.meeting_glossary_entries (owner_user_id uuid not null, meeting_id uuid not null, glossary_entry_id uuid not null, primary key(owner_user_id,meeting_id,glossary_entry_id), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade, foreign key(owner_user_id,glossary_entry_id) references public.glossary_entries(owner_user_id,id) on delete cascade);
create table public.meeting_summaries (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, meeting_id uuid not null, version integer not null default 1, content text not null, created_at timestamptz not null default now(), unique(owner_user_id,id), unique(owner_user_id,meeting_id,version), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade);
create table public.audio_artifacts (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, session_id uuid, meeting_id uuid, storage_path text not null, kind text not null, created_at timestamptz not null default now(), unique(owner_user_id,id), unique(owner_user_id,storage_path), foreign key(owner_user_id,session_id) references public.sessions(owner_user_id,id) on delete cascade, foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade);
create table public.export_artifacts (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, meeting_id uuid, storage_path text not null, format text not null, created_at timestamptz not null default now(), unique(owner_user_id,id), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade);
create table public.viewer_shares (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null, meeting_id uuid not null, token_hash text, short_code_hash text, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), unique(owner_user_id,id), unique(token_hash), unique(short_code_hash), foreign key(owner_user_id,meeting_id) references public.meetings(owner_user_id,id) on delete cascade, check(token_hash is not null or short_code_hash is not null));
create table public.gemini_credentials (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, encrypted_value text not null, last_four text, key_version text not null, verified_at timestamptz, created_at timestamptz not null default now(), unique(owner_user_id,id));
do $$ declare t text; begin foreach t in array array['profiles','meetings','meeting_segments','sessions','subtitle_cues','translation_requests','translation_executions','translation_outputs','glossary_categories','glossary_entries','meeting_glossary_entries','meeting_summaries','audio_artifacts','export_artifacts','viewer_shares','gemini_credentials'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant all on public.%I to service_role',t); if t='profiles' then execute 'grant select on public.profiles to authenticated'; execute 'create policy profiles_select on public.profiles for select using(auth.uid()=id)'; else execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I_select on public.%I for select using(auth.uid()=owner_user_id)',t||'_select',t); execute format('create policy %I_insert on public.%I for insert with check(auth.uid()=owner_user_id)',t||'_insert',t); execute format('create policy %I_update on public.%I for update using(auth.uid()=owner_user_id) with check(auth.uid()=owner_user_id)',t||'_update',t); execute format('create policy %I_delete on public.%I for delete using(auth.uid()=owner_user_id)',t||'_delete',t); end if; end loop; end $$;
revoke all on public.gemini_credentials from anon,authenticated;
